import{_ as a,o as t,c as i,a7 as o}from"./chunks/framework.FWlv_suP.js";const h=JSON.parse('{"title":"Office Orbit Data Collection","description":"Official data-collection summary for Office Orbit.","frontmatter":{"title":"Office Orbit Data Collection","description":"Official data-collection summary for Office Orbit.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-collection/office-orbit.md","filePath":"data-collection/office-orbit.md"}'),r={name:"data-collection/office-orbit.md"};function n(s,e,c,l,d,f){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="office-orbit-data-collection" tabindex="-1">Office Orbit Data Collection <a class="header-anchor" href="#office-orbit-data-collection" aria-label="Permalink to &quot;Office Orbit Data Collection&quot;">​</a></h1><p><strong>Last reviewed:</strong> September 8, 2026</p><h2 id="information-processed" tabindex="-1">Information processed <a class="header-anchor" href="#information-processed" aria-label="Permalink to &quot;Information processed&quot;">​</a></h2><p>Office Orbit retrieves authenticated work records from its API. These can include work logs, comments, project and company relationships, JIRA details, sprint plans and allocations, release information, feedback, work links, dashboard summaries, and analytics.</p><p>The sign-in password is sent to the authentication endpoint over HTTPS. The username field supports credential-manager identification and is not sent by the Office Orbit client to its API.</p><h2 id="information-stored-locally" tabindex="-1">Information stored locally <a class="header-anchor" href="#information-stored-locally" aria-label="Permalink to &quot;Information stored locally&quot;">​</a></h2><p>The app stores access-token and session timing information in browser session storage on the web and secure device storage on Android. An optional PIN is represented by a salted verifier. Android performs optional biometric authentication without providing biometric templates to Office Orbit.</p><p>Fetched work data and navigation state are cached in memory and cleared on sign-out. Selected work-log data is included in a PDF only when you request an export.</p><h2 id="network-and-third-party-processing" tabindex="-1">Network and third-party processing <a class="header-anchor" href="#network-and-third-party-processing" aria-label="Permalink to &quot;Network and third-party processing&quot;">​</a></h2><p>The configured Cloudflare Workers API receives authentication and data requests plus ordinary connection metadata. GitHub Pages processes ordinary delivery logs for the web app. External sites receive information when you choose to open their links. These providers apply their own terms and privacy policies.</p><h2 id="advertising-and-analytics" tabindex="-1">Advertising and analytics <a class="header-anchor" href="#advertising-and-analytics" aria-label="Permalink to &quot;Advertising and analytics&quot;">​</a></h2><p>Office Orbit contains no advertising, developer-operated analytics, or telemetry service.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Questions can be sent to <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p>',14)])])}const m=a(r,[["render",n]]);export{h as __pageData,m as default};
